"use strict";(globalThis.webpackChunkpaper=globalThis.webpackChunkpaper||[]).push([[8797],{2488:n=>{n.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"/ai_element","metadata":{"permalink":"/paper/dev/ai_element","source":"@site/dev/ai_element.md","title":"1. AI \uae30\ubcf8 \uad6c\uc131 \uc694\uc18c","description":"AI \uc2dc\uc2a4\ud15c\uc744 \uc774\uc6a9\ud558\uae30 \uc704\ud55c \uae30\ubcf8 \uac1c\ub150 Model, Agent, Harness \uac00 \ubb34\uc5c7\uc778\uc9c0 \uc54c\uc544\ubcf4\uc544\uc694.","date":"2026-11-01T00:00:00.000Z","tags":[],"readingTime":4.56,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"1. AI \uae30\ubcf8 \uad6c\uc131 \uc694\uc18c","description":"AI \uc2dc\uc2a4\ud15c\uc744 \uc774\uc6a9\ud558\uae30 \uc704\ud55c \uae30\ubcf8 \uac1c\ub150 Model, Agent, Harness \uac00 \ubb34\uc5c7\uc778\uc9c0 \uc54c\uc544\ubcf4\uc544\uc694.","image":"https://images.unsplash.com/photo-1677918903267-c213ce2c1ff8?q=80&w=2274&auto=format&fit=crop&ixlib=rb-4.1.0&ixid=NHwxMjA3fDA%3D","date":"2026-11-01T00:00:00.000Z"},"unlisted":false,"nextItem":{"title":"2. AI \uc791\uc5c5 \uc218\ud589 \ubc29\uc2dd","permalink":"/paper/dev/ai_working"}},"content":"AI\uc5d0\uac8c \uc77c\uc744 \uc2dc\ud0a4\ub294 \ubc29\ubc95, AI\uac00 \uc77c\ud558\ub294 \ud658\uacbd\uc744 \ub9cc\ub4dc\ub294 \ubc29\ubc95, AI \uac00 \uc791\uc5c5\uc744 \uc5f0\uacb0\ud558\ub294 \ubc29\ubc95 \ub4f1 \uc11c\ub85c\ub2e4\ub978 \uc601\uc5ed\uc744 \uc124\uba85\ud558\uace0 \uc788\uc5b4\uc694.\\n\\n## 1. AI \ubaa8\ub378(AI Model)\\n\\n> \uc0dd\uac01\ud558\uace0 \ud310\ub2e8\ud558\ub294 \ub450\ub1cc\\n\\n\ub300\ub7c9\uc758 \ub370\uc774\ud130\ub97c \ud559\uc2b5\ud574\uc11c \ud328\ud134\uc744 \uc775\ud788\uace0, \uc0c8\ub85c\uc6b4 \uc785\ub825\uc744 \ubc1b\uc558\uc744 \ub54c \uacb0\uacfc\ub97c \ub9cc\ub4e4\uc5b4 \ub0b4\ub294 \uc2dc\uc2a4\ud15c\uc774\uc5d0\uc694.\\n\ub300\ud45c\uc801\uc73c\ub85c GPT, Claude, Gemini \ubaa8\ub378\uc774 \uc788\uc5b4\uc694.\\n\\n## 2. AI \uc5d0\uc774\uc804\ud2b8(Agent)\\n\\n> \ubaa9\ud45c\ub97c \ubc1b\uace0 \uc2a4\uc2a4\ub85c \uc791\uc5c5\uc744 \uc9c4\ud589\ud558\ub294 \uc77c\uafbc\\n\\n\uc5d0\uc774\uc804\ud2b8\uc758 \ud070 \ud2b9\uc9d5\uc740 \uc2a4\uc2a4\ub85c \ub2e4\uc74c \ud589\ub3d9\uc744 \uacb0\uc815\ud558\uace0, \uc2e4\ud589\ud560 \uc218 \uc788\ub2e4\ub294 \uc810\uc774\uc5d0\uc694. \\n\uc77c\ubc18\uc801\uc73c\ub85c AI\uc5d0\uac8c \uad81\uae08\ud55c \uac83\ub4e4\uc744 \ubb3c\uc5b4\ubcf4\uace0 \ub2f5\ubcc0\uc744 \ubc1b\uc796\uc544\uc694. \ubc18\uba74 \uc5d0\uc774\uc804\ud2b8\uc5d0\uac8c\ub294 \ubaa9\ud45c\ub97c \uc8fc\uc5b4\uc57c \ud574\uc694. \uadf8\ub7fc \uc5d0\uc774\uc804\ud2b8\ub294 \uadf8 \ubaa9\ud45c\ub97c \ub2ec\uc131\ud558\uae30 \uc704\ud574 \ud544\uc694\ud55c \uc791\uc5c5\ub4e4\uc744 \uacc4\ud68d\ud558\uace0 \uc2e4\ud589\ud574\uc694.\\n\\n\uc77c\ubc18 \uc801\uc778 AI\uc5d0\uac8c \uc694\uccad\\n\\"\uc774 \ucf54\ub4dc\uc5d0\uc11c \ubb38\uc81c\uac00 \uc788\ub294 \ubd80\ubd84\uc744 \ucc3e\uc544\uc918.\\" -> \ucf54\ub4dc\ub97c \ubd84\uc11d\ud558\uace0 \ubb38\uc81c\uc810\uc744 \uc54c\ub824\uc90d\ub2c8\ub2e4. \uadf8\ub7fc \uadf8 \ubb38\uc81c\ub97c \ud574\uacb0\ud558\ub77c\uace0 \ub610 \uc694\uccad\ud574\uc57c \uaca0\uc8e0.\\n\\n\uc5d0\uc774\uc804\ud2b8\uc5d0\uac8c \uc694\uccad\\n\\"\uc774 \ud504\ub85c\uc81d\ud2b8\uc5d0\uc11c \uba54\ubaa8\ub9ac \ub204\uc218 \ubb38\uc81c\ub97c \ucc3e\uc544\uc11c \ud574\uacb0\ud574\uc918\\" -> \ud504\ub85c\uc81d\ud2b8\ub97c \ud0d0\uc0c9\ud558\uace0, \ubd84\uc11d\ud574\uc11c, \ucf54\ub4dc\ub97c \uc218\uc815\ud558\uace0, \uacb0\uacfc\uae4c\uc9c0 \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc5d0\uc774\uc804\ud2b8\uc5d0 \uc5b4\ub290\ubc94\uc704\uae4c\uc9c0 \uc2e4\ud589\ud560 \uc218 \uc788\ub294\uc9c0 \uad8c\ud55c\uc744 \uc8fc\ub290\ub0d0\uc5d0 \ub530\ub77c \uacb0\uacfc\uac00 \ub2ec\ub77c\uc838\uc694.\\n\\n## 3. \ud504\ub86c\ud504\ud2b8 \uc5d4\uc9c0\ub2c8\uc5b4\ub9c1(Prompt Engineering)\\n\\n> AI \uc5d0\uac8c \uc6d0\ud558\ub294 \uacb0\uacfc\ub97c \uc5bb\uae30\uc704\ud574 \uc9c8\ubb38\uc774\ub098 \uc9c0\uc2dc\ubb38(Prompt)\uc744 \ud6a8\uacfc\uc801\uc73c\ub85c \uc791\uc131\ud558\ub294 \uae30\uc220\\n\\n\uc608\ub97c \ub4e4\uc5b4 AI\uc5d0\uac8c \ub2e4\uc74c\uacfc \uac19\uc774 \uc694\uccad\ud55c\ub2e4\uace0 \ud574\ubcfc\uac8c\uc694.\\n\\n\uc77c\ubc18\uc801\uc778 \ud504\ub86c\ud504\ud2b8\\n\\"Swift \ucf54\ub4dc\ub97c \ub9ac\ud329\ud1a0\ub9c1\ud574 \uc918.\\"\\n\\n\uad6c\uccb4\uc801\uc778 \ud504\ub86c\ud504\ud2b8\\n\\"\uc774 Swift \ucf54\ub4dc\ub97c \ub9ac\ud329\ud1a0\ub9c1\ud574 \uc918.\\n- \uae30\uc874 \uae30\ub2a5\uc740 \uc720\uc9c0\ud574 \uc918.\\n- \uc911\ubcf5 \ucf54\ub4dc\ub97c \uc81c\uac70\ud574 \uc918.\\n- \uba54\ubaa8\ub9ac \uad00\ub9ac \uce21\uba74\uc5d0\uc11c \ubb38\uc81c\uac00 \uc5c6\ub294\uc9c0 \ud655\uc778\ud574 \uc918.\\n- \ubcc0\uacbd\ud55c \uc774\uc720\ub97c \uc124\uba85\ud574 \uc918.\\"\\n\\n\ub450 \uc694\uccad \ubaa8\ub450 \uac19\uc740 \uc791\uc5c5\uc744 \uc694\uad6c\ud558\uc9c0\ub9cc, \ub450 \ubc88\uc9f8 \uc694\uccad\uc740 \ubaa9\ud45c\uc640 \uc870\uac74\uc774 \ub354 \uba85\ud655\ud574\uc694.\\n\\n\uc774\ucc98\ub7fc \ud504\ub86c\ud504\ud2b8\ub97c \uc5b4\ub5bb\uac8c \uc791\uc131\ud574\uc57c AI\uac00 \uc6d0\ud558\ub294 \ubc29\ud5a5\uc73c\ub85c \uc791\uc5c5\ud560\uc9c0 \uace0\ubbfc\ud558\ub294 \uac83\uc774 \ud504\ub86c\ud504\ud2b8 \uc5d4\uc9c0\ub2c8\uc5b4\ub9c1\uc774\uc5d0\uc694.\\n\\n## 4. \ucee8\ud14d\uc2a4\ud2b8 \uc5d4\uc9c0\ub2c8\uc5b4\ub9c1(Context Engineering)\\n\\n> AI \uc5d0\uac8c \ud544\uc694\ud55c \uc815\ubcf4\ub97c \uc798 \uad6c\uc131\ud574\uc11c \uc81c\uacf5\ud558\ub294 \uae30\uc220\\n\\nAI\uac00 \uc791\uc5c5\uc744 \uc81c\ub300\ub85c \uc218\ud589\ud560 \uc218 \uc788\ub3c4\ub85d \ud544\uc694\ud55c \uc815\ubcf4(Context)\ub97c \uc218\uc9d1\ud558\uace0 \uad6c\uc131\ud574\uc11c \uc81c\uacf5\ud558\ub294 \uae30\uc220\uc774\uc5d0\uc694.\\n\\nAI \uc5d0\uac8c \ub9ac\ud329\ud1a0\ub9c1\uc744 \uc694\uccad\ud558\ub354\ub77c\ub3c4 AI\uac00 \ud504\ub85c\uc81d\ud2b8 \uad6c\uc870\ub97c \ubaa8\ub974\uba74 \uc801\uc808\ud55c \ucf54\ub4dc\ub97c \uc791\uc131\ud558\uae30 \uc5b4\ub824\uc6b8 \uc218 \uc788\uc5b4\uc694. \uc774\ub54c \uac1c\ubc1c\ud658\uacbd, \uc544\ud0a4\ud14d\ucc98, \ud504\ub85c\uc81d\ud2b8 \uaddc\uce59, \ucc38\uace0 \uc790\ub8cc\ub97c \uac19\uc774 \uc81c\uacf5\ud558\ub294 \uac70\uc608\uc694. \uc774\ub7f0 \uc815\ubcf4\ub97c AI\uac00 \ucc38\uace0\ud560 \uc218 \uc788\ub3c4\ub85d \uad6c\uc131\ud558\uba74, \ud504\ub85c\uc81d\ud2b8\uc5d0 \uc0c1\ud669\uc5d0 \ub9de\ub294 \uacb0\uacfc\ubb3c\uc744 \ub9cc\ub4e4 \uac00\ub2a5\uc131\uc774 \ub192\uc544\uc838\uc694.\\n\\n## 5. \ud558\ub124\uc2a4(Harness)\\n\\n> AI\uac00 \uc81c\ub300\ub85c \uc77c\ud560 \uc218 \uc788\ub3c4\ub85d \ub9cc\ub4e4\uc5b4 \uc8fc\ub294 \uc2e4\ud589 \ud658\uacbd\\n\\nHareness\ub294 \uc6d0\ub798 \uc7a5\ube44\ub97c \uace0\uc815\ud558\ub294 \uc7a5\uce58\ub77c\ub294 \uc758\ubbf8\uac00 \uc788\uc5b4\uc694. AI\ubd84\uc57c\uc5d0\uc11c\ub294 AI \uc5d0\uc774\uc804\ud2b8\uac00 \uc548\uc815\uc801\uc73c\ub85c \uc791\uc5c5\ud560 \uc218 \uc788\ub3c4\ub85d \uc8fc\ubcc0 \ud658\uacbd\uacfc \uaddc\uce59\uc744 \uad6c\uc131\ud558\ub294 \uac83\uc744 \uc758\ubbf8\ud574\uc694."},{"id":"/ai_working","metadata":{"permalink":"/paper/dev/ai_working","source":"@site/dev/ai_working.md","title":"2. AI \uc791\uc5c5 \uc218\ud589 \ubc29\uc2dd","description":"AI \uac00 \uc2e4\uc81c\ub85c \uc791\uc5c5\ud558\ub294 \ubc29\ubc95 Skill, Memory, RAG, MCP","date":"2026-11-02T00:00:00.000Z","tags":[],"readingTime":2.95,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"2. AI \uc791\uc5c5 \uc218\ud589 \ubc29\uc2dd","description":"AI \uac00 \uc2e4\uc81c\ub85c \uc791\uc5c5\ud558\ub294 \ubc29\ubc95 Skill, Memory, RAG, MCP","image":"https://images.unsplash.com/photo-1583521214690-73421a1829a9?q=80&w=2670&auto=format&fit=crop&ixlib=rb-4.1.0&ixid=NHwxMjA3fDA%3D","date":"2026-11-02T00:00:00.000Z"},"unlisted":false,"prevItem":{"title":"1. AI \uae30\ubcf8 \uad6c\uc131 \uc694\uc18c","permalink":"/paper/dev/ai_element"},"nextItem":{"title":"3. AI \uc791\uc5c5 \ud504\ub85c\uc138\uc2a4","permalink":"/paper/dev/ai_process"}},"content":"## 1. \uc2a4\ud0ac(Skill)\\n\\n> \ud2b9\uc815 \uc791\uc5c5\uc744 \uc218\ud589\ud558\ub294 \ubc29\ubc95\uc744 \ubbf8\ub9ac \uc815\uc758\ud55c \uba54\ub274\uc5bc\\n\\n\ub9e4\ubc88 AI\uc5d0\uac8c \uc791\uc5c5 \ubc29\ubc95\uc744 \uc124\uba85\ud558\ub294 \ub300\uc2e0, \ud574\ub2f9 \uc791\uc5c5\uc758 \uaddc\uce59\uacfc \uc808\ucc28\ub97c \uc2a4\ud0ac\ub85c \ub9cc\ub4e4\uc5b4 \ub193\ub294 \uac70\uc608\uc694.\\n\\n\uc608\uc2dc: Swift Code Review Skill\\n\\n\uc774 \uc2a4\ud0ac\uc774 \uc2e4\ud589\ub418\uba74 \ub2e4\uc74c\uc744 \uc218\ud589\ud55c\ub2e4.\\n\\n1. Swift \ucf54\ub4dc\ub97c \ubd84\uc11d\ud55c\ub2e4.\\n2. \uba54\ubaa8\ub9ac \ub204\uc218 \uac00\ub2a5\uc131\uc744 \ud655\uc778\ud55c\ub2e4.\\n3. retain cycle\uc774 \ubc1c\uc0dd\ud560 \uc218 \uc788\ub294\uc9c0 \ud655\uc778\ud55c\ub2e4.\\n4. Swift Concurrency \uc0ac\uc6a9\uc774 \uc801\uc808\ud55c\uc9c0 \ud655\uc778\ud55c\ub2e4.\\n5. \uac1c\uc120\ud560 \ubd80\ubd84\uc744 \uc774\uc720\uc640 \ud568\uaed8 \uc81c\uc548\ud55c\ub2e4.\\n\\n\uc774\ud6c4 AI\uc5d0\uac8c \ucf54\ub4dc \ub9ac\ubdf0\ub97c \uc694\uccad\ud558\uba74 \uc2a4\ud0ac\uc5d0 \uc815\uc758\ub41c \ubc29\uc2dd\uc73c\ub85c \uc791\uc5c5\ud574\uc694.\\n\\n## 2. \uba54\ubaa8\ub9ac(Memory)\\n\\n> \uc774\uc804 \uc815\ubcf4\ub97c \uc800\uc7a5\ud558\uace0 \ud65c\uc6a9\ud558\ub294 \uae30\ub2a5\\n\\nAI\uac00 \uc774\uc804\uc5d0 \uc54c\uac8c\ub41c \uc815\ubcf4\ub97c \uc774\ud6c4 \ub300\ud654\ub098 \uc791\uc5c5\uc5d0\uc11c \ud65c\uc6a9\ud558\ub294 \uac1c\ub150\uc774\uc5d0\uc694. Memory \uc5d0\ub294 \uc0ac\uc6a9\uc790 \uc120\ud638 \uc815\ubcf4, \uc9c4\ud589\uc911\uc778 \uc791\uc5c5\uc758 \uc0c1\ud0dc, \uc774\uc804\uc5d0 \uacb0\uc815\ud55c \uc0ac\ud56d, \ubc18\ubcf5\uc801\uc73c\ub85c \ud65c\uc6a9\ud574\uc57c \ud558\ub294 \uc815\ubcf4 \ub4f1\uc774 \uc788\uc5b4\uc694.\\n\\nMemory \uc640 Context \ub294 \uac19\uc740 \uac1c\ub150\uc774 \uc544\ub2c8\uc5d0\uc694.\\n- Memory: \uae30\uc5b5\ud574 \ub450\ub294 \uc815\ubcf4\\n- Context: \ud604\uc7ac \uc791\uc5c5\uc744 \uc218\ud589\ud558\uae30 \uc704\ud574 AI\uc5d0\uac8c \uc81c\uacf5 \ub418\ub294 \uc815\ubcf4\\n\\nMemory\uc5d0 \uc800\uc7a5\ub41c \uc815\ubcf4\uac00 \ub2e4\uc74c \uc791\uc5c5\uc758 Context \ub85c \ud65c\uc6a9 \ub420 \uc218 \uc788\ub294 \uac70\uc608\uc694.\\n\\n## 3. RAG(Retrieval-Augmented Generation)\\n\\n> \uc678\ubd80 \uc790\ub8cc\ub97c \uac80\uc0c9\ud574\uc11c AI\ub2f5\ubcc0\uc5d0 \ud65c\uc6a9\ud558\ub294 \uae30\uc220\\n\\n\uc678\ubd80\uc5d0\uc11c \uad00\ub828 \uc815\ubcf4\ub97c \uac80\uc0c9\ud574 AI\uc5d0\uac8c \uc81c\uacf5\ud558\uace0, \uadf8 \uc815\ubcf4\ub97c \ubc14\ud0d5\uc73c\ub85c \ub2f5\ubcc0\uc744 \uc0dd\uc131\ud558\ub294 \ubc29\uc2dd\uc774\uc5d0\uc694. RAG\ub294 AI\uac00 \ubb38\uc11c\ub97c \ubbf8\ub9ac \uc804\ubd80 \ud559\uc2b5\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c, \uc9c8\ubb38\uc774 \ub4e4\uc5b4\uc654\uc744 \ub54c \ud544\uc694\ud55c \ub0b4\uc6a9\uc744 \ucc3e\uc544\uc11c \ucc38\uace0 \ud574\uc694.\\n\\n## 4. MCP(Model Context Protocol)\\n\\n> AI\uc640 \uc678\ubd80 \ub3c4\uad6c\ub97c \uc5f0\uacb0\ud558\uae30 \uc704\ud55c \uacf5\ud1b5 \ud1b5\uc2e0 \uaddc\uaca9\\n\\nAI\uac00 \uc678\ubd80 \ub3c4\uad6c\ub098 \ub370\uc774\ud130\uc5d0 \uc5f0\uacb0\ud560 \ub54c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294 \ud45c\uc900\ud654\ub41c \ud1b5\uc2e0 \uaddc\uaca9\uc774\uc5d0\uc694. \uc608\ub97c\ub4e4\uc5b4 \\"GitHub\uc5d0\uc11c \ud604\uc7ac \uc9c4\ud589\uc911\uc778 Issue \ubaa9\ub85d\uc744 \ud655\uc778\ud574\uc918\\"\ub77c\uace0 \uc694\uccad\ud588\ub2e4\uace0 \uc0dd\uac01\ud574 \ubcfc\uac8c\uc694. \uadf8\ub7f0\ub370 AI \uac00 GitHub\uc5d0 \uc811\uadfc \ud560 \uc218 \uc5c6\ub2e4\uba74 \uc774 \uc791\uc5c5\uc744 \uc9c4\ud589\ud560 \uc218 \uc5c6\uaca0\uc8e0? \uc774\ub54c GitHub MCP Server\uac00 \uc788\ub2e4\uba74 AI\uac00 GitHub \uae30\ub2a5\uc744 \uc0ac\uc6a9\ud560 \uc218 \uc788\ub3c4\ub85d \uc5f0\uacb0\ud574 \uc904 \uc218 \uc788\uc5b4\uc694."},{"id":"/ai_process","metadata":{"permalink":"/paper/dev/ai_process","source":"@site/dev/ai_process.md","title":"3. AI \uc791\uc5c5 \ud504\ub85c\uc138\uc2a4","description":"AI \uac00 \uc791\uc5c5\uc744 \uc5f0\uacb0\ud558\uace0 \uc9c4\ud589\ud558\ub294 \ubc29\ubc95","date":"2026-11-03T00:00:00.000Z","tags":[],"readingTime":4.65,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"3. AI \uc791\uc5c5 \ud504\ub85c\uc138\uc2a4","description":"AI \uac00 \uc791\uc5c5\uc744 \uc5f0\uacb0\ud558\uace0 \uc9c4\ud589\ud558\ub294 \ubc29\ubc95","image":"https://images.unsplash.com/photo-1580203784276-6ded72fea88a?q=80&w=2274&auto=format&fit=crop&ixlib=rb-4.1.0&ixid=NHwxMjA3fDA%3D","date":"2026-11-03T00:00:00.000Z"},"unlisted":false,"prevItem":{"title":"2. AI \uc791\uc5c5 \uc218\ud589 \ubc29\uc2dd","permalink":"/paper/dev/ai_working"},"nextItem":{"title":"4. AI \ud488\uc9c8 \ubc0f \uc548\uc815\uc131","permalink":"/paper/dev/ai_eval_guardrails"}},"content":"## Agentic Workflow\\n\\n> AI\uac00 \uc5ec\ub7ec \ub2e8\uacc4\ub97c \uac70\uccd0 \uc791\uc5c5\uc744 \uc218\ud589\ud558\ub294 \ud750\ub984\\n\\n\ud558\ub098\uc758 \ubaa9\ud45c\ub098 \uc694\uad6c\uc0ac\ud56d\uc744 \uc804\ub2ec\ud558\uba74, AI\uac00 \ubaa9\ud45c \ub2ec\uc131\uc5d0 \ud544\uc694\ud55c \uc791\uc5c5\ub4e4\uc744 \uc5ec\ub7ec \ub2e8\uacc4\ub85c \ub098\ub204\uace0, \uac01 \uc791\uc5c5\uc758 \uc21c\uc11c\uc640 \uad00\uacc4\ub97c \uad6c\uc131\ud558\uc5ec \ucd5c\uc885 \ubaa9\ud45c\ub97c \ub2ec\uc131\ud558\ub294 \uc791\uc5c5 \ud750\ub984\uc774\uc5d0\uc694.\\n\\n## Agent Orchestration\\n\\n> \uc5ec\ub7ec AI \uc5d0\uc774\uc804\ud2b8\uc758 \uc5ed\ud560\uacfc \uc791\uc5c5 \uc21c\uc11c\ub97c \uc870\uc728\ud558\ub294 \uac83\\n\\n\uc5ec\ub7ec AI \uc5d0\uc774\uc804\ud2b8\uc5d0\uac8c \uc5ed\ud560\uacfc \uc791\uc5c5\uc744 \ubd84\ubc30\ud558\uace0, \uac01 \uc5d0\uc774\uc804\ud2b8\uc758 \uc2e4\ud589 \uc21c\uc11c\uc640 \uacb0\uacfc\ubb3c\uc744 \uc870\uc728\ud558\uc5ec \ud558\ub098\uc758 \ubaa9\ud45c\ub97c \ub2ec\uc131\ud558\ub3c4\ub85d \uad00\ub9ac\ud558\ub294 \uac83\uc774\uc5d0\uc694.\\n\\n| \uac1c\ub150 | \uc758\ubbf8 |\\n| :--| :--|\\n| Agent | \uc2e4\uc81c \uc791\uc5c5\uc744 \uc218\ud589\ud558\ub294 \uc8fc\uccb4 |\\n| Orchestrator | Agent\ub4e4\uc758 \uc5ed\ud560\uacfc \uc791\uc5c5\uc744 \uc870\uc728\ud558\ub294 \uc8fc\uccb4 |\\n| Orchestration | \uc804\uccb4 \uc870\uc728 \uacfc\uc815 | \\n\\n## Loop Engineering\\n\\n> \uacb0\uacfc\ub97c \ud655\uc778\ud558\uace0 \uc218\uc815\ud558\ub294 \ubc18\ubcf5 \uad6c\uc870\ub97c \uc124\uacc4\ud558\ub294 \uac83\\n\\nAI \uac00 \uc791\uc5c5\ud55c \uacb0\uacfc\ub97c \ud655\uc778\ud558\uace0, \ubd80\uc871\ud558\uac70\ub098 \uc798\ubabb\ub41c \ubd80\ubd84\uc744 \uc218\uc815\ud55c \ub4a4 \ub2e4\uc2dc \uc2e4\ud589\ud558\ub294 \ubc18\ubcf5 \uad6c\uc870\ub97c \uc124\uacc4\ud558\ub294 \uac83\uc774\uc5d0\uc694. \ub2e4\uc2dc \ub9d0\ud574 AI \uc5d0\uac8c \ud55c\ubc88\uc5d0 \uc644\ubcbd\ud55c \uacb0\uacfc\ub97c \uae30\ub300\ud558\ub294 \uac8c \uc544\ub2c8\ub77c, \uacb0\uacfc\ub97c \ud655\uc778\ud558\uace0 \uacc4\uc18d \uac1c\uc120\ud558\ub3c4\ub85d \ub9cc\ub4dc\ub294 \uac70\uc608\uc694.\\n\\n## Graph Engineering\\n\\n> \uc791\uc5c5\uc758 \uc21c\uc11c, \uc870\uac74 \ubd84\uae30, \ubc18\ubcf5 \uad00\uacc4\ub97c \uadf8\ub798\ud504\ub85c \uc124\uacc4\ud558\ub294 \uac83\\n\\n\uc791\uc5c5\uc744 \uc77c\ub82c\ub85c \ub098\uc5f4\ud558\ub294 \ub300\uc2e0, \uac01 \uc791\uc5c5\uc744 **\ub178\ub4dc(Node)** \ub85c, \uc791\uc5c5 \uc0ac\uc774\uc758 \uc5f0\uacb0\uc744 **\uc5e3\uc9c0(Edge)** \ub85c \ud45c\ud604\ud574 \uc804\uccb4 \ud750\ub984\uc744 \uadf8\ub798\ud504\ub85c \uc124\uacc4\ud558\ub294 \uac83\uc774\uc5d0\uc694.\\n\\n| \uc694\uc18c | \uc758\ubbf8 | \uc608\uc2dc |\\n| :-- | :-- | :-- |\\n| \ub178\ub4dc(Node) | \ud558\ub098\uc758 \uc791\uc5c5, \ub610\ub294 \uadf8 \uc791\uc5c5\uc744 \ub9e1\uc740 Agent | \uad6c\ud604, \ud14c\uc2a4\ud2b8 |\\n| \uc5e3\uc9c0(Edge) | \ub2e4\uc74c \uc791\uc5c5\uc73c\ub85c \ub118\uc5b4\uac00\ub294 \uc5f0\uacb0 | \uad6c\ud604 \u2192 \ud14c\uc2a4\ud2b8 |\\n| \uc870\uac74 \ubd84\uae30 | \uacb0\uacfc\uc5d0 \ub530\ub77c \ub2e4\ub978 \ub178\ub4dc\ub85c \uc774\ub3d9 | \ud1b5\uacfc \u2192 \uc644\ub8cc, \uc2e4\ud328 \u2192 \uc218\uc815 |\\n| \uc0ac\uc774\ud074(Cycle) | \uc774\uc804 \ub178\ub4dc\ub85c \ub418\ub3cc\uc544\uac00\ub294 \uc5f0\uacb0 | \uc218\uc815 \u2192 \ub2e4\uc2dc \ud14c\uc2a4\ud2b8 |\\n\\n\uc608\ub97c \ub4e4\uc5b4 \ub85c\uadf8\uc778 \uae30\ub2a5 \uad6c\ud604\uc744 \uadf8\ub798\ud504\ub85c \ub098\ud0c0\ub0b4\uba74 \uc774\ub807\uac8c \ub3fc\uc694.\\n\\n```mermaid\\nflowchart LR\\n  A[\uc694\uad6c\uc0ac\ud56d \ubd84\uc11d] --\x3e B[\uc124\uacc4]\\n  B --\x3e C[API \uad6c\ud604]\\n  B --\x3e D[\ud654\uba74 \uad6c\ud604]\\n  C --\x3e E{\ud14c\uc2a4\ud2b8}\\n  D --\x3e E\\n  E -- \uc2e4\ud328 --\x3e F[\uc218\uc815]\\n  F --\x3e E\\n  E -- \ud1b5\uacfc --\x3e G[\uc644\ub8cc]\\n```\\n\\n- **\uc758\uc874\uc131**: \uc124\uacc4\uac00 \ub05d\ub098\uba74 API\uc640 \ud654\uba74\uc744 \ub3d9\uc2dc\uc5d0 \uad6c\ud604\ud560 \uc218 \uc788\uace0, \ud14c\uc2a4\ud2b8\ub294 \ub450 \uc791\uc5c5\uc774 \ubaa8\ub450 \ub05d\ub098\uc57c \uc2dc\uc791\ud574\uc694.\\n- **\uc870\uac74 \ubd84\uae30**: \ud14c\uc2a4\ud2b8 \uacb0\uacfc\uc5d0 \ub530\ub77c \uc644\ub8cc\ub85c \uac00\uac70\ub098 \uc218\uc815\uc73c\ub85c \uac00\uc694.\\n- **\ubc18\ubcf5**: \uc218\uc815 \ud6c4 \ub2e4\uc2dc \ud14c\uc2a4\ud2b8\ub85c \ub3cc\uc544\uac00\uc694. Loop Engineering\uc5d0\uc11c \uc124\uacc4\ud55c \ubc18\ubcf5\uc774 \uadf8\ub798\ud504\uc5d0\uc11c\ub294 \uc774\ub807\uac8c \ub418\ub3cc\uc544\uac00\ub294 \ud654\uc0b4\ud45c\ub85c \ud45c\ud604\ub3fc\uc694.\\n\\nLangGraph \uac19\uc740 \ud504\ub808\uc784\uc6cc\ud06c\uac00 \uc774\ub7f0 \ubc29\uc2dd\uc73c\ub85c \ub178\ub4dc\uc640 \uc5e3\uc9c0\ub97c \uc815\uc758\ud574\uc11c Agent\uc758 \uc791\uc5c5 \ud750\ub984\uc744 \uad6c\uc131\ud574\uc694.\\n\\n## 4\uac00\uc9c0 \uac1c\ub150 \uc5f0\uacb0\ud558\uae30\\n\\n| \uac1c\ub150 | \ud575\uc2ec \uc9c8\ubb38 | \ud575\uc2ec \uc5ed\ud560 |\\n| :--| :--| :-- |\\n| Agentic Workflow | \uc5b4\ub5a4 \uc791\uc5c5\uc744 \uc9c4\ud589\ud560\uae4c? | \uc804\uccb4 \uc791\uc5c5 \ud750\ub984 \uc124\uacc4 |\\n| Agent Orchestration | \ub204\uac00 \uc791\uc5c5\ud560\uae4c? | Agent \uc5ed\ud560 \ubc0f \uc2e4\ud589 \uc870\uc728 | \\n| Loop Engineering | \uc5b4\ub5bb\uac8c \ubc18\ubcf5 \uac1c\uc120\ud560\uae4c? | \uac80\uc99d\uacfc \uc218\uc815 \ubc18\ubcf5 \uad6c\uc870 | \\n| Graph Engineering | \uc791\uc5c5\ub4e4\uc774 \uc5b4\ub5bb\uac8c \uc5f0\uacb0\ub420\uae4c? | \ub178\ub4dc\uc640 \uc5f0\uacb0 \uad00\uacc4 \uc124\uacc4 |\\n\\n\ud558\ub098\uc758 AI \uac1c\ubc1c \uc2dc\uc2a4\ud15c \uc548\uc5d0\uc11c \ud568\uaed8 \ud65c\uc6a9\ud560 \uc218 \uc788\ub294\ub370\uc694.\\n\uc608\ub97c \ub4e4\uc5b4 \ub85c\uadf8\uc778 \uae30\ub2a5\uc744 \uad6c\ud604\ud558\ub294 AI \uc2dc\uc2a4\ud15c\uc5d0\uc11c\\n- Workflow \ub85c \uc804\uccb4 \uc791\uc5c5 \ub2e8\uacc4\ub97c \uc815\ud558\uace0, \\n- Orchestration \uc73c\ub85c \uc5ec\ub7ec Agent \uc5d0\uac8c \uc5ed\ud560\uc744 \ub098\ub204\uace0, \\n- Loop \ub85c \ud14c\uc2a4\ud2b8\uc640 \uc218\uc815\uc744 \ubc18\ubcf5\ud558\uace0, \\n- Graph \ub85c \uc791\uc5c5 \uac04 \uc758\uc874\uc131\uacfc \ubd84\uae30\ub97c \ud45c\ud604\ud560 \uc218 \uc788\uc5b4\uc694."},{"id":"/ai_eval_guardrails","metadata":{"permalink":"/paper/dev/ai_eval_guardrails","source":"@site/dev/ai_eval_guardrails.md","title":"4. AI \ud488\uc9c8 \ubc0f \uc548\uc815\uc131","description":"AI\uac00 \uc791\uc5c5\ud55c \uacb0\uacfc\uac00 \uc81c\ub300\ub85c \ub41c \uac83\uc778\uc9c0, \uadf8\ub9ac\uace0 AI\uac00 \ud574\ub3c4 \ub418\ub294 \uc77c\uc758 \ubc94\uc704\ub97c \uc5b4\ub5bb\uac8c \uad00\ub9ac\ud560 \uac83\uc778\uc9c0","date":"2026-11-04T00:00:00.000Z","tags":[],"readingTime":2.18,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"4. AI \ud488\uc9c8 \ubc0f \uc548\uc815\uc131","description":"AI\uac00 \uc791\uc5c5\ud55c \uacb0\uacfc\uac00 \uc81c\ub300\ub85c \ub41c \uac83\uc778\uc9c0, \uadf8\ub9ac\uace0 AI\uac00 \ud574\ub3c4 \ub418\ub294 \uc77c\uc758 \ubc94\uc704\ub97c \uc5b4\ub5bb\uac8c \uad00\ub9ac\ud560 \uac83\uc778\uc9c0","image":"https://images.unsplash.com/photo-1592844002373-a55ecd7af140?q=80&w=2670&auto=format&fit=crop&ixlib=rb-4.1.0&ixid=NHwxMjA3fDA%3D","date":"2026-11-04T00:00:00.000Z"},"unlisted":false,"prevItem":{"title":"3. AI \uc791\uc5c5 \ud504\ub85c\uc138\uc2a4","permalink":"/paper/dev/ai_process"},"nextItem":{"title":"5. AI \ud65c\uc6a9 \ubc0f \ud655\uc7a5","permalink":"/paper/dev/ai_extension"}},"content":"## Evaluation\\n\\n> AI\uac00 \ub9cc\ub4e0 \uacb0\uacfc\uac00 \uae30\ub300\ud55c \uc218\uc900\uc778\uc9c0 \uce21\uc815\ud558\ub294 \uac83\\n\\nAI\ub294 \uac19\uc740 \uc785\ub825\uc5d0\ub3c4 \ub9e4\ubc88 \ub2e4\ub978 \uacb0\uacfc\ub97c \ub0bc \uc218 \uc788\uc5b4\uc11c, \ud55c \ubc88 \uc798 \ub410\ub2e4\uace0 \ud488\uc9c8\uc774 \ubcf4\uc7a5\ub418\uc9c0 \uc54a\uc544\uc694. \uadf8\ub798\uc11c \uae30\uc900\uacfc \ud14c\uc2a4\ud2b8 \ub370\uc774\ud130\ub97c \uc815\ud574\ub450\uace0 \uacb0\uacfc\ub97c \ubc18\ubcf5\ud574\uc11c \uce21\uc815\ud574\uc694.\\n\\n| \ubc29\uc2dd | \uc758\ubbf8 | \uc608\uc2dc |\\n| :-- | :-- | :-- |\\n| \uaddc\uce59 \uae30\ubc18 | \uc815\ub2f5\uc774\ub098 \uaddc\uce59\uacfc \uc9c1\uc811 \ube44\uad50 | \ud14c\uc2a4\ud2b8 \ud1b5\uacfc \uc5ec\ubd80, JSON \ud615\uc2dd \uac80\uc0ac |\\n| \uc0ac\ub78c \ud3c9\uac00 | \uc0ac\ub78c\uc774 \uacb0\uacfc\ub97c \uc9c1\uc811 \ubcf4\uace0 \ud310\ub2e8 | \ucf54\ub4dc \ub9ac\ubdf0, \ub2f5\ubcc0 \ub9cc\uc871\ub3c4 |\\n| LLM-as-a-Judge | \ub2e4\ub978 AI\uac00 \uae30\uc900\uc5d0 \ub530\ub77c \ucc44\uc810 | \\"\uc9c8\ubb38\uc5d0 \ub9de\ub294 \ub2f5\uc778\uac00?\\" 1~5\uc810 |\\n\\n\ud504\ub86c\ud504\ud2b8\ub098 \ubaa8\ub378\uc744 \ubc14\uafe8\uc744 \ub54c \uc815\ub9d0 \ub098\uc544\uc84c\ub294\uc9c0\ub3c4 \uac19\uc740 \uae30\uc900\uc73c\ub85c \ube44\uad50\ud560 \uc218 \uc788\uc5b4\uc694.\\n\\n## Guardrails\\n\\n> AI\uac00 \ud574\ub3c4 \ub418\ub294 \uc77c\uacfc \ud558\uba74 \uc548 \ub418\ub294 \uc77c\uc758 \uacbd\uacc4\ub97c \uc815\ud558\ub294 \uac83\\n\\nAI\uac00 \uc704\ud5d8\ud55c \uc791\uc5c5\uc744 \uc2e4\ud589\ud558\uac70\ub098 \uc798\ubabb\ub41c \uc815\ubcf4\ub97c \ub0b4\ubcf4\ub0b4\uc9c0 \uc54a\ub3c4\ub85d, \uc785\ub825\xb7\ucd9c\ub825\xb7\ud589\ub3d9\uc5d0 \uc81c\ud55c\uc744 \ub450\ub294 \uc7a5\uce58\uc608\uc694.\\n\\n| \uc704\uce58 | \ud558\ub294 \uc77c | \uc608\uc2dc |\\n| :-- | :-- | :-- |\\n| \uc785\ub825 | \ub4e4\uc5b4\uc624\ub294 \uc694\uccad\uc744 \uac80\uc0ac | \uac1c\uc778\uc815\ubcf4, \ud504\ub86c\ud504\ud2b8 \uc778\uc81d\uc158 \ucc28\ub2e8 |\\n| \ucd9c\ub825 | \ub0b4\ubcf4\ub0b4\ub294 \uacb0\uacfc\ub97c \uac80\uc0ac | \ubbfc\uac10 \uc815\ubcf4 \ub9c8\uc2a4\ud0b9, \ud615\uc2dd \uac80\uc99d |\\n| \ud589\ub3d9 | \uc2e4\ud589\ud560 \uc218 \uc788\ub294 \uc791\uc5c5\uc744 \uc81c\ud55c | \ud30c\uc77c \uc0ad\uc81c\xb7\ubc30\ud3ec \uc804 \uc0ac\ub78c \uc2b9\uc778 |\\n\\n## \ub450 \uac1c\ub150 \ube44\uad50\ud558\uae30\\n\\n| \uac1c\ub150 | \ud575\uc2ec \uc9c8\ubb38 | \uc2dc\uc810 |\\n| :-- | :-- | :-- |\\n| Evaluation | \uacb0\uacfc\uac00 \uc798 \ub098\uc654\ub098? | \uacb0\uacfc\uac00 \ub098\uc628 \ub4a4 \uce21\uc815 |\\n| Guardrails | \ud574\ub3c4 \ub418\ub294 \uc77c\uc778\uac00? | \uc2e4\ud589 \uc804\xb7\uc2e4\ud589 \uc911 \ucc28\ub2e8 |\\n\\nEvaluation\uc740 \ud488\uc9c8\uc744 \ub192\uc774\uace0, Guardrails\ub294 \uc0ac\uace0\ub97c \ub9c9\uc544\uc694. Loop Engineering\uc5d0\uc11c\ub294 Evaluation \uacb0\uacfc\uac00 \ub2e4\uc2dc \uc218\uc815\ud560\uc9c0 \ud310\ub2e8\ud558\ub294 \uae30\uc900\uc774 \ub3fc\uc694."},{"id":"/ai_extension","metadata":{"permalink":"/paper/dev/ai_extension","source":"@site/dev/ai_extension.md","title":"5. AI \ud65c\uc6a9 \ubc0f \ud655\uc7a5","description":"AI \uac00 \uac1c\uc778\uc758 \uc9c0\uc2dd \uad00\ub9ac \ubc29\uc2dd\uacfc \uc77c\ud558\ub294 \ubc29\uc2dd \uc790\uccb4\ub97c \uc5b4\ub5bb\uac8c \ubc14\uafc0\uc218 \uc788\ub294\uc9c0 \uc54c\uc544\ubcfc\uac8c\uc694.","date":"2026-11-04T15:17:00.000Z","tags":[],"readingTime":2.425,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"5. AI \ud65c\uc6a9 \ubc0f \ud655\uc7a5","description":"AI \uac00 \uac1c\uc778\uc758 \uc9c0\uc2dd \uad00\ub9ac \ubc29\uc2dd\uacfc \uc77c\ud558\ub294 \ubc29\uc2dd \uc790\uccb4\ub97c \uc5b4\ub5bb\uac8c \ubc14\uafc0\uc218 \uc788\ub294\uc9c0 \uc54c\uc544\ubcfc\uac8c\uc694.","image":"https://images.unsplash.com/photo-1711409645921-ef3db0501f96?q=80&w=3264&auto=format&fit=crop&ixlib=rb-4.1.0&ixid=NHwxMjA3fDA%3D","date":"2026-11-04T15:17:00.000Z"},"unlisted":false,"prevItem":{"title":"4. AI \ud488\uc9c8 \ubc0f \uc548\uc815\uc131","permalink":"/paper/dev/ai_eval_guardrails"}},"content":"## Second Brain\\n\\n> \uba38\ub9bf\uc18d \uc9c0\uc2dd\uc744 \ubc16\uc5d0 \uc800\uc7a5\ud574\ub450\uace0 \ud544\uc694\ud560 \ub54c \uaebc\ub0b4 \uc4f0\ub294 \uac1c\uc778 \uc9c0\uc2dd \uc2dc\uc2a4\ud15c\\n\\n\uc0ac\ub78c\uc740 \ubaa8\ub4e0 \uc815\ubcf4\ub97c \uae30\uc5b5\ud560 \uc218 \uc5c6\uc796\uc544\uc694. \uadf8\ub798\uc11c \uae30\uc5b5\ud574\uc57c \ud560 \uc815\ubcf4\ub098 \ub098\uc911\uc5d0 \ud65c\uc6a9\ud560 \uc9c0\uc2dd\uc744 \uc678\ubd80 \uacf5\uac04\uc5d0 \uc815\ub9ac\ud558\uace0, \ud544\uc694\ud560 \ub54c \ub2e4\uc2dc \uaebc\ub0b4 \uc4f8 \uc218 \uc788\ub3c4\ub85d \ub9cc\ub4dc\ub294 \uac70\uc608\uc694. \uc77d\uc740 \uae00, \uba54\ubaa8, \uc544\uc774\ub514\uc5b4\ub97c \ud55c\uacf3\uc5d0 \ubaa8\uc544\ub450\uace0 \ub2e4\uc2dc \ud65c\uc6a9\ud558\ub294\uac70\uc8e0. \uc774 \ube14\ub85c\uadf8\ub3c4 \uacf5\ubd80\ud55c \ub0b4\uc6a9\uc744 \uae30\ub85d\ud574\ub450\ub294 \uac83\uc73c\ub85c Second Brain\uc774\uc5d0\uc694.\\n\\n\uc804\uc5d0\ub294 \ubaa8\uc73c\uace0 \uc815\ub9ac\ud558\ub294 \uc77c\uc744 \uc0ac\ub78c\uc774 \ub2e4 \ud588\ub2e4\uba74, \uc774\uc81c\ub294 AI\uac00 \ub9ce\uc740 \ubd80\ubd84\uc744 \ub9e1\uc544\uc694. \ub2e8\uc21c\ud788 \uc815\ubcf4\ub97c \uc800\uc7a5\ud558\ub294 \ub370 \uadf8\uce58\uc9c0 \uc54a\uace0, AI\uac00 \uc800\uc7a5\ub41c \uc9c0\uc2dd\uc744 \uac80\uc0c9\ud558\uace0 \uc5f0\uacb0\ud574\uc11c \ud65c\uc6a9\ud560 \uc218 \uc788\uac8c \ub41c\uac70\uc608\uc694.\\n\\n## AI Native\\n\\n> \ucc98\uc74c\ubd80\ud130 AI\uc640 \ud568\uaed8 \uc77c\ud55c\ub2e4\ub294 \uc804\uc81c\ub85c \uc77c\ud558\ub294 \ubc29\uc2dd\uc744 \uc124\uacc4\ud558\ub294 \uac83\\n\\nAI\ub97c \uae30\uc874 \uc5c5\ubb34\uc5d0 \ub2e8\uc21c\ud788 \ucd94\uac00\ud558\ub294 \uac8c \uc544\ub2c8\ub77c, \ucc98\uc74c\ubd80\ud130 AI\ub97c \ud65c\uc6a9\ud558\ub294 \uac83\uc744 \uc804\uc81c\ub85c \uc5c5\ubb34\uc640 \uc2dc\uc2a4\ud15c\uc744 \uc124\uacc4\ud558\ub294 \uc811\uadfc \ubc29\uc2dd\uc774\uc5d0\uc694.\\n\\n| \uad6c\ubd84 | AI-enabled | AI Native |\\n| :-- | :-- | :-- |\\n| AI\uc758 \uc5ed\ud560 | \ud544\uc694\ud560 \ub54c \uc4f0\ub294 \ub3c4\uad6c | \ud568\uaed8 \uc77c\ud558\ub294 \ub3d9\ub8cc |\\n| \uc0ac\ub78c\uc758 \uc5ed\ud560 | \uc9c1\uc811 \uc791\uc5c5 | \ubaa9\ud45c \uc124\uc815, \uac80\ud1a0, \ud310\ub2e8 |\\n| \uc608\uc2dc | \ucf54\ub4dc\ub97c \uc9e0 \ub4a4 AI\uc5d0\uac8c \ub9ac\ubdf0 \uc694\uccad | \uc694\uad6c\uc0ac\ud56d\uc744 \uc8fc\uba74 AI\uac00 \uad6c\ud604\xb7\ud14c\uc2a4\ud2b8\ud558\uace0 \uc0ac\ub78c\uc740 \uac80\ud1a0 |\\n\\n\uc0ac\ub78c\uc758 \uc77c\uc774 \uc9c1\uc811 \ub9cc\ub4dc\ub294 \uac83\uc5d0\uc11c, \ubb34\uc5c7\uc744 \uc2dc\ud0ac\uc9c0 \uc815\ud558\uace0(Workflow) \uacb0\uacfc\ub97c \ud655\uc778\ud558\ub294(Evaluation) \uac83\uc73c\ub85c \uc62e\uaca8\uac00\uc694.\\n\\n## \uc815\ub9ac\\n\\nSecond Brain\uc740 **\uc544\ub294 \ubc29\uc2dd**\uc744, AI Native\ub294 **\uc77c\ud558\ub294 \ubc29\uc2dd**\uc744 \ubc14\uafd4\uc694. \ub458 \ub2e4 \ubc18\ubcf5\uc801\uc778 \uc77c\uc740 AI\uc5d0\uac8c \ub9e1\uae30\uace0, \uc0ac\ub78c\uc740 \ubc29\ud5a5\uc744 \uc815\ud558\uace0 \ud310\ub2e8\ud558\ub294 \ub370 \uc9d1\uc911\ud55c\ub2e4\ub294 \uc810\uc5d0\uc11c \uac19\uc544\uc694."}]}}')}}]);